(()=>{
 const C=JourneyCore,KEY='benjamin-friend-journey-v1',esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let storageAvailable=true,state;try{state=C.normalize(JSON.parse(localStorage.getItem(KEY)),journeyLevels)}catch{state=C.fresh();storageAvailable=false}
 let selectedClue=null,pair=[],answer=null,feedback='',journalOpen=false,routeOpen=false,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const app=document.getElementById('game'),sourceCache=new Map();journeyLevels.forEach(l=>l.clues.forEach(c=>sourceCache.set(l.id+':'+c[0],C.source(c,chapters))));
 const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true}catch{storageAvailable=false}};
 const level=()=>journeyLevels[state.current],lensText={wander:'游荡者视角：留意人如何移动、停留和观看。',collect:'收藏家视角：留意物件的用途、磨损与归属。',research:'研究者视角：留意材料的出处、时间与相互冲突。'};
 function sourceCard(key,full=false){let s=sourceCache.get(key);if(!s)return '<p>本线索尚无材料。</p>';return `<blockquote class="source-quote">${esc(full?s.text:s.text.slice(0,360))}${!full&&s.text.length>360?'…':''}</blockquote><p class="source-label">${s.matched?'导览摘录／解读':'相关主题材料'} · ${esc(s.title)}</p><a href="index.html#read/${s.chapter}/${s.pos}" target="_blank" rel="noopener">查阅卷轴上下文 ↗</a>`}
 function route(){let unlocked=C.unlocked(state,journeyLevels);return `<section class="route-panel" ${routeOpen?'':'hidden'}><h2>巴黎同行路线</h2><p>游戏路线连接历史记忆，跨区使用场景转场。</p><ol>${journeyLevels.map((l,i)=>`<li><button data-action="travel" data-index="${i}" ${i>unlocked?'disabled':''} ${i===state.current?'aria-current="step"':''}><small>${i===0?'序':i===11?'终':String(i).padStart(2,'0')}</small><span>${l.title}<em>${l.place}</em></span><b>${i>unlocked?'未解锁':state.completed.includes(l.id)?'已寄出':'可进入'}</b></button></li>`).join('')}</ol></section>`}
 function journal(){let inv=C.inventory(state,journeyLevels);return `<section class="journal-panel" ${journalOpen?'':'hidden'}><div class="panel-heading"><h2>随身札记 · Carnet</h2><button data-action="export">导出札记</button></div><p>${inv.length} 份碎片 · ${state.completed.length} 封阶段札记已寄出</p>${inv.map(x=>`<details><summary>${esc(x.label)} · ${esc(journeyLevels.find(l=>l.id===x.level).title)}</summary>${sourceCard(x.key)}</details>`).join('')||'<p>点击场景中的线索，把第一份材料放入札记。</p>'}<label class="note-label">给朋友的观察<textarea id="reflection" maxlength="5000" placeholder="哪些事物之间的关系改变了你对巴黎的理解？">${esc(state.reflection)}</textarea></label><button data-action="reset" class="quiet">重新开始游戏</button></section>`}
 function intro(){return `<section class="invitation"><div class="invitation-art"><img src="assets/unique/place-richelieu.jpg" alt="巴黎图书馆的油画式艺术演绎"></div><div class="invitation-copy"><p class="fr">Une amitié à Paris</p><h1>与本雅明同行</h1><p>巴黎，一封来自朋友的邀请。你将协助本雅明寻找街道、访问人物、保存碎片，最终写下自己的巴黎札记。</p><label>你的称呼<input id="friend-name" maxlength="30" value="${esc(state.name)}" placeholder="可以留空，成为一位同行的朋友"></label><fieldset><legend>从哪一种观察开始？随时可以切换。</legend>${[['wander','游荡者','看人群与街道'],['collect','收藏家','看物件与记忆'],['research','研究者','看出处与关系']].map(([v,t,d])=>`<label><input type="radio" name="lens" value="${v}" ${state.lens===v?'checked':''}><span>${t}<small>${d}</small></span></label>`).join('')}</fieldset><button data-action="begin" class="primary">收下邀请，开始同行 ↗</button><p class="notice">独立游戏 · 序章、十关与终章 · 自动保存在当前浏览器。对白为原创，材料卡来自现有导览。</p><a href="index.html">继续自由浏览网站 ↗</a></div></section>`}
 function cluePanel(){let l=level(),clue=l.clues.find(c=>c[0]===selectedClue);if(!clue)return `<section class="clue-panel"><p class="fr">Regarder de près</p><h2>从场景中寻找线索</h2><p>${l.task}</p><p class="lens-note">${lensText[state.lens]}</p><a href="index.html#dossier/${l.archive}" target="_blank" rel="noopener">地点与人物档案 ↗</a></section>`;return `<section class="clue-panel" id="clue-reading"><p class="fr">Fragment recueilli</p><h2 tabindex="-1">${clue[1]}</h2><p>${clue[2]}</p><p class="lens-note">${lensText[state.lens]}</p>${sourceCard(l.id+':'+clue[0])}<p class="notice">已放入随身札记。查阅网站会在新标签打开，游戏进度保留。</p></section>`}
 function puzzle(){let l=level(),collected=state.collected[l.id]||[],solved=state.solved[l.id];return `<section class="puzzle"><div><p class="fr">Mettre en relation</p><h2>把碎片放在一起</h2><p>${l.question}</p><p class="notice">先搜集场景线索，选择其中两份，再选择你的解释。</p></div><div class="puzzle-controls"><div class="evidence-pair" role="group" aria-label="选择两份材料">${l.clues.map(c=>`<button data-action="pair" data-clue="${c[0]}" aria-pressed="${pair.includes(c[0])}" ${!collected.includes(c[0])?'disabled':''}>${collected.includes(c[0])?'':'尚未找到 · '}${c[1]}</button>`).join('')}</div><fieldset class="interpretations"><legend>你的解释</legend>${l.options.map((o,i)=>`<label><input type="radio" name="interpretation" value="${i}" ${answer===i?'checked':''}>${o}</label>`).join('')}</fieldset><div class="actions"><button class="primary" data-action="connect" ${pair.length<2||answer===null?'disabled':''}>连接材料</button><button class="quiet" data-action="hint">需要一点提示</button></div><p class="feedback" role="status">${esc(feedback|| (solved?l.explanation:''))}</p>${solved?'<button class="primary next-stop" data-action="next">寄出这一页札记，前往下一站 ↗</button>':''}</div></section>`}
 function finale(){let inv=C.inventory(state,journeyLevels);return `<section class="finale"><div class="finale-heading"><p class="fr">Une lettre pour Walter</p><h1>在醒来之前</h1><p>${journeyLevels[11].message}</p><p class="notice">从至少三个不同幕中选择三份材料，写下不少于八个字符的观察。你的作品标为玩家创作。</p></div><div class="montage-grid">${inv.map(x=>`<button data-action="montage" data-key="${x.key}" aria-pressed="${state.finalSelection.includes(x.key)}"><small>${journeyActs[x.act]}</small><strong>${esc(x.label)}</strong><span>${esc(sourceCache.get(x.key)?.text.slice(0,140)||'')}</span></button>`).join('')}</div><label class="note-label">交给本雅明的巴黎札记<textarea id="final-reflection" maxlength="5000" placeholder="我把这三份碎片放在一起，因为……">${esc(state.reflection)}</textarea></label><p id="montage-status" role="status">已选择 ${state.finalSelection.length}/3 份碎片</p><button class="primary" data-action="finish" ${C.canFinish(state,journeyLevels)?'':'disabled'}>把札记交给朋友 ↗</button></section>`}
 function ending(){return `<section class="ending"><p class="fr">La ville reste ouverte</p><h1>朋友，巴黎仍未写完。</h1><p>你已走完这一段同行路线。留下的是一份玩家创作的札记，而不是替本雅明完成的原著。</p><div class="player-letter"><p>给瓦尔特：</p><p>${esc(state.reflection).replace(/\n/g,'<br>')}</p><p>你的朋友，${esc(state.name||'同行者')}</p></div><div class="ending-sources">${state.finalSelection.map(k=>`<details><summary>${esc(C.inventory(state,journeyLevels).find(x=>x.key===k)?.label||'材料')}</summary>${sourceCard(k,true)}</details>`).join('')}</div><div class="actions"><button class="primary" data-action="export">导出我的巴黎札记</button><a href="index.html#atlas">回到自由探索的巴黎 ↗</a><button data-action="journal">查看所有碎片</button></div></section>`}
 function render(){document.body.classList.toggle('reduced',reduced);document.getElementById('motion-toggle').setAttribute('aria-pressed',String(reduced));document.getElementById('motion-toggle').textContent=reduced?'开启动效':'减少动效';if(!state.started){app.innerHTML=intro();bindInputs();return}let l=level();app.innerHTML=`<div class="journey-toolbar"><div><p>${journeyActs[l.act]}</p><span>${state.completed.length}/11 阶段已完成 · ${C.inventory(state,journeyLevels).length} 份碎片</span></div><div class="actions"><button data-action="route" aria-expanded="${routeOpen}">巴黎路线</button><button data-action="journal" aria-expanded="${journalOpen}">随身札记</button><select id="lens" aria-label="观察视角"><option value="wander" ${state.lens==='wander'?'selected':''}>游荡者视角</option><option value="collect" ${state.lens==='collect'?'selected':''}>收藏家视角</option><option value="research" ${state.lens==='research'?'selected':''}>研究者视角</option></select></div></div>${!storageAvailable?'<p class="storage-warning" role="status">当前浏览器未能保存进度，请及时导出札记，并保留此页面。</p>':''}${route()}${journal()}${state.finished&&l.id==='montage'?ending():l.id==='montage'?finale():`<section class="stage-heading"><p class="fr">${l.fr}</p><h1>${l.title}</h1><p>${l.place} · ${esc(state.name||'朋友')}，${l.task}</p></section><section class="companion"><img src="assets/unique/person-benjamin.jpg" alt="本雅明艺术演绎肖像"><div><span>本雅明致朋友 · 原创游戏对白</span><p>${l.message}</p></div></section><div class="exploration"><section class="scene" aria-label="${l.place}的游戏场景"><img class="scene-painting" src="assets/unique/${l.image}.jpg" alt="${l.place}油画场景，艺术演绎">${l.clues.map(c=>`<button class="hotspot ${(state.collected[l.id]||[]).includes(c[0])?'found':''}" style="left:${c[5]}%;top:${c[6]}%" data-action="collect" data-clue="${c[0]}" aria-label="观察${c[1]}"><i></i><span>${c[1]}</span></button>`).join('')}<span class="scene-caption">场景为艺术演绎；热点用于引导观察。</span></section>${cluePanel()}</div>${puzzle()}`}`;bindInputs()}
 function bindInputs(){let name=document.getElementById('friend-name');if(name)name.oninput=e=>{state.name=e.target.value;save()};document.querySelectorAll('input[name=lens]').forEach(r=>r.onchange=()=>{state.lens=r.value;save()});let lens=document.getElementById('lens');if(lens)lens.onchange=()=>{state.lens=lens.value;save();render()};document.querySelectorAll('input[name=interpretation]').forEach(r=>r.onchange=()=>{answer=+r.value;render()});for(let id of ['reflection','final-reflection']){let el=document.getElementById(id);if(el)el.oninput=e=>{state.reflection=e.target.value;save();let finish=document.querySelector('[data-action=finish]');if(finish)finish.disabled=!C.canFinish(state,journeyLevels)}}}
 function exportNotes(){let inv=C.inventory(state,journeyLevels);let lines=['与本雅明同行 · 玩家巴黎札记','玩家：'+(state.name||'同行者'),'原创游戏体验，非本雅明原著。','',state.reflection,'','材料目录：'];inv.forEach(x=>{let s=sourceCache.get(x.key);lines.push('\n'+x.label+' · '+journeyLevels.find(l=>l.id===x.level).title,s.text,'出处：导览摘录／解读 · '+s.title+' · 段落 '+(s.pos+1),'index.html#read/'+s.chapter+'/'+s.pos)});let url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='与本雅明同行-巴黎札记.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 app.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b||b.disabled)return;let a=b.dataset.action,l=level();if(a==='begin'){state.started=true;save();render()}else if(a==='route'){routeOpen=!routeOpen;render()}else if(a==='journal'){journalOpen=!journalOpen;render()}else if(a==='collect'){if(C.collect(state,l,b.dataset.clue)){selectedClue=b.dataset.clue;save();render();document.querySelector('#clue-reading h2')?.focus({preventScroll:true})}}else if(a==='pair'){let id=b.dataset.clue;if(pair.includes(id))pair=pair.filter(k=>k!==id);else{if(pair.length===2)pair.shift();pair.push(id)}feedback='';render()}else if(a==='connect'){let result=C.connect(state,l,pair,answer);feedback=result.reason;save();render()}else if(a==='hint'){feedback='试着比较“'+l.clues.find(c=>c[0]===l.pair[0])[1]+'”与“'+l.clues.find(c=>c[0]===l.pair[1])[1]+'”。回查出处，再选择能解释两者联系的说法。';render()}else if(a==='next'){if(C.complete(state,journeyLevels,state.current)){selectedClue=null;pair=[];answer=null;feedback='';save();render();window.scrollTo(0,0)}}else if(a==='travel'){let i=+b.dataset.index;if(i<=C.unlocked(state,journeyLevels)){state.current=i;selectedClue=null;pair=[];answer=null;feedback='';save();render();window.scrollTo(0,0)}}else if(a==='montage'){let k=b.dataset.key;if(state.finalSelection.includes(k))state.finalSelection=state.finalSelection.filter(x=>x!==k);else if(state.finalSelection.length<3)state.finalSelection.push(k);save();render()}else if(a==='finish'){if(C.canFinish(state,journeyLevels)){state.finished=true;save();render();window.scrollTo(0,0)}}else if(a==='export')exportNotes();else if(a==='reset')document.getElementById('reset-dialog').showModal()});
 document.getElementById('motion-toggle').onclick=()=>{reduced=!reduced;render()};document.getElementById('cancel-reset').onclick=()=>document.getElementById('reset-dialog').close();document.getElementById('confirm-reset').onclick=()=>{state=C.fresh();selectedClue=null;pair=[];answer=null;feedback='';journalOpen=routeOpen=false;save();document.getElementById('reset-dialog').close();render()};save();render();
})();
